-- 外部系统集成基础设施：系统注册、幂等同步任务、重试和审计字段。
-- 不在数据库保存密钥；认证引用只对应部署环境中的密钥名称。
BEGIN;

CREATE TABLE IF NOT EXISTS "外部系统" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "系统代码" varchar(50) NOT NULL,
    "系统名称" varchar(100) NOT NULL,
    "系统类型" varchar(30) NOT NULL,
    "基础地址" varchar(500),
    "认证方式" varchar(30) NOT NULL DEFAULT '无',
    "认证引用" varchar(200),
    "是否启用" boolean NOT NULL DEFAULT FALSE,
    "超时秒数" integer NOT NULL DEFAULT 15,
    "最大重试次数" integer NOT NULL DEFAULT 3,
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_外部系统" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_外部系统_代码" UNIQUE ("系统代码"),
    CONSTRAINT "ck_外部系统_类型" CHECK ("系统类型" IN ('HR','财务','采购','伦理','合同','人才库','生物样本库','论文采集','其他')),
    CONSTRAINT "ck_外部系统_认证方式" CHECK ("认证方式" IN ('无','Bearer','Basic','ApiKey','OIDC')),
    CONSTRAINT "ck_外部系统_超时" CHECK ("超时秒数" BETWEEN 1 AND 120),
    CONSTRAINT "ck_外部系统_重试" CHECK ("最大重试次数" BETWEEN 0 AND 10)
);

CREATE TABLE IF NOT EXISTS "外部同步任务" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "外部系统编号" bigint NOT NULL,
    "业务类型" varchar(80) NOT NULL,
    "方向" varchar(10) NOT NULL,
    "业务主键" varchar(150),
    "幂等键" varchar(200) NOT NULL,
    "请求负载" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "状态" varchar(10) NOT NULL DEFAULT '待处理',
    "尝试次数" integer NOT NULL DEFAULT 0,
    "最大重试次数" integer NOT NULL DEFAULT 3,
    "下次重试时间" timestamp without time zone,
    "请求ID" varchar(100),
    "外部响应摘要" varchar(2000),
    "最后错误" varchar(2000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "完成时间" timestamp without time zone,
    CONSTRAINT "pk_外部同步任务" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_外部同步任务_系统" FOREIGN KEY ("外部系统编号") REFERENCES "外部系统"("编号"),
    CONSTRAINT "uq_外部同步任务_幂等键" UNIQUE ("幂等键"),
    CONSTRAINT "ck_外部同步任务_方向" CHECK ("方向" IN ('推送','拉取')),
    CONSTRAINT "ck_外部同步任务_状态" CHECK ("状态" IN ('待处理','处理中','成功','失败','已取消')),
    CONSTRAINT "ck_外部同步任务_尝试次数" CHECK ("尝试次数" >= 0),
    CONSTRAINT "ck_外部同步任务_重试次数" CHECK ("最大重试次数" BETWEEN 0 AND 10)
);

CREATE INDEX IF NOT EXISTS "ix_外部同步任务_状态时间"
    ON "外部同步任务" ("状态", "下次重试时间", "创建时间");
CREATE INDEX IF NOT EXISTS "ix_外部同步任务_系统业务"
    ON "外部同步任务" ("外部系统编号", "业务类型", "创建时间" DESC);

UPDATE "系统迁移版本"
   SET "版本" = 54,
       "脚本" = '001-054',
       "检查摘要" = '增加外部系统注册和幂等同步任务队列，认证密钥仅引用部署环境配置'
 WHERE "编号" = 1;

COMMIT;
